import{c as e,Q as i,j as s,m as t}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第二章：安装 Claude Code","description":"在你的电脑上安装 Claude Code","frontmatter":{"title":"第二章：安装 Claude Code","description":"在你的电脑上安装 Claude Code"},"headers":[],"relativePath":"guide/1-getting-started/2-installation.md","filePath":"guide/1-getting-started/2-installation.md"}'),l={name:"guide/1-getting-started/2-installation.md"};function o(n,a,d,r,h,p){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="第二章-安装-claude-code" tabindex="-1">第二章：安装 Claude Code <a class="header-anchor" href="#第二章-安装-claude-code" aria-label="Permalink to &quot;第二章：安装 Claude Code&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你能在自己电脑上成功安装 Claude Code，并了解编程中常用的几个运行环境。</p></div><h2 id="什么是终端-命令行" tabindex="-1">什么是终端/命令行？ <a class="header-anchor" href="#什么是终端-命令行" aria-label="Permalink to &quot;什么是终端/命令行？&quot;">​</a></h2><p><strong>终端</strong>（Terminal）是一个用文字命令来操作电脑的程序。就像电影里黑客用的那种黑底绿字的界面。</p><ul><li><strong>Windows</strong>：PowerShell 或 Windows Terminal</li><li><strong>Mac</strong>：Terminal（在 Applications &gt; Utilities 里）</li></ul><h2 id="编程运行环境简介" tabindex="-1">编程运行环境简介 <a class="header-anchor" href="#编程运行环境简介" aria-label="Permalink to &quot;编程运行环境简介&quot;">​</a></h2><p>开始安装之前，先了解几个常用的运行环境，Claude Code 的安装和它们有关。</p><h3 id="node-js-—-javascript-运行时" tabindex="-1">Node.js — JavaScript 运行时 <a class="header-anchor" href="#node-js-—-javascript-运行时" aria-label="Permalink to &quot;Node.js — JavaScript 运行时&quot;">​</a></h3><p>Node.js 让 JavaScript 可以在服务器端运行。Claude Code 本身就是用 Node.js 开发的，安装 Claude Code 需要先装 Node.js。</p><p>官网：<a href="https://nodejs.org" target="_blank" rel="noreferrer">https://nodejs.org</a></p><h3 id="python-—-数据和脚本语言" tabindex="-1">Python — 数据和脚本语言 <a class="header-anchor" href="#python-—-数据和脚本语言" aria-label="Permalink to &quot;Python — 数据和脚本语言&quot;">​</a></h3><p>Python 适合数据分析、人工智能、自动化脚本。很多工具包括 AI 相关的库都用 Python 开发。</p><p>官网：<a href="https://python.org" target="_blank" rel="noreferrer">https://python.org</a></p><h3 id="git-—-版本控制工具" tabindex="-1">Git — 版本控制工具 <a class="header-anchor" href="#git-—-版本控制工具" aria-label="Permalink to &quot;Git — 版本控制工具&quot;">​</a></h3><p>Git 用来追踪代码的修改历史、团队协作。Claude Code 的很多操作会涉及 Git（比如查看修改、回退版本）。</p><p>官网：<a href="https://git-scm.com" target="_blank" rel="noreferrer">https://git-scm.com</a></p><div class="tip custom-block"><p class="custom-block-title">小提示</p><p>这些工具的安装教程见下方章节。已有安装经验的可以直接跳过。</p></div><h2 id="windows-用户安装步骤" tabindex="-1">Windows 用户安装步骤 <a class="header-anchor" href="#windows-用户安装步骤" aria-label="Permalink to &quot;Windows 用户安装步骤&quot;">​</a></h2><h3 id="_1-安装-windows-terminal" tabindex="-1">1. 安装 Windows Terminal <a class="header-anchor" href="#_1-安装-windows-terminal" aria-label="Permalink to &quot;1. 安装 Windows Terminal&quot;">​</a></h3><p>Windows 11 自带 Windows Terminal。Windows 10 可以从 Microsoft Store 免费安装。</p><h3 id="_2-安装-node-js" tabindex="-1">2. 安装 Node.js <a class="header-anchor" href="#_2-安装-node-js" aria-label="Permalink to &quot;2. 安装 Node.js&quot;">​</a></h3><p>从 <a href="https://nodejs.org" target="_blank" rel="noreferrer">https://nodejs.org</a> 下载安装包，选择 LTS（长期支持版）。</p><h3 id="_3-安装-claude-code" tabindex="-1">3. 安装 Claude Code <a class="header-anchor" href="#_3-安装-claude-code" aria-label="Permalink to &quot;3. 安装 Claude Code&quot;">​</a></h3><p>打开 PowerShell 或 Windows Terminal，输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">小提示</p><p>如果提示需要管理员权限，右键选择&quot;以管理员身份运行&quot;终端。</p></div><h3 id="_4-验证安装成功" tabindex="-1">4. 验证安装成功 <a class="header-anchor" href="#_4-验证安装成功" aria-label="Permalink to &quot;4. 验证安装成功&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>看到版本号就说明安装成功了。</p><h2 id="mac-用户安装步骤" tabindex="-1">Mac 用户安装步骤 <a class="header-anchor" href="#mac-用户安装步骤" aria-label="Permalink to &quot;Mac 用户安装步骤&quot;">​</a></h2><h3 id="_1-打开-terminal" tabindex="-1">1. 打开 Terminal <a class="header-anchor" href="#_1-打开-terminal" aria-label="Permalink to &quot;1. 打开 Terminal&quot;">​</a></h3><p>按 <code>Command + Space</code>，搜索&quot;Terminal&quot;，回车打开。</p><h3 id="_2-安装-node-js-1" tabindex="-1">2. 安装 Node.js <a class="header-anchor" href="#_2-安装-node-js-1" aria-label="Permalink to &quot;2. 安装 Node.js&quot;">​</a></h3><p>推荐用 Homebrew 安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/bin/bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span></span></code></pre></div><h3 id="_3-安装-claude-code-1" tabindex="-1">3. 安装 Claude Code <a class="header-anchor" href="#_3-安装-claude-code-1" aria-label="Permalink to &quot;3. 安装 Claude Code&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><h3 id="_4-验证安装成功-1" tabindex="-1">4. 验证安装成功 <a class="header-anchor" href="#_4-验证安装成功-1" aria-label="Permalink to &quot;4. 验证安装成功&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 提示&quot;找不到命令&quot;？</strong></p><p>A: 重启终端，或者完全关闭再重新打开。</p><p><strong>Q: 杀毒软件报警？</strong></p><p>A: 正常现象，因为 Claude Code 会读写文件。信任该软件即可。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>打开终端，输入 <code>node --version</code> 确认 Node.js 安装成功</li><li>输入 <code>git --version</code> 确认 Git 安装成功</li><li>输入 <code>claude --version</code> 确认 Claude Code 安装成功</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>安装完成后，下一章我们会学习如何获取和配置 API Key。</p><p><a href="/claude-code-guide/guide/1-getting-started/3-api-key-setup.html">👉 第三章：API Key 获取与配置</a></p>`,49)])])}const k=e(l,[["render",o]]);export{u as __pageData,k as default};
